package uk.ac.ravensbourne.casevault.web; import static org.junit.jupiter.api.Assertions.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import java.nio.file.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class SecurityHeadersTest { @Autowired MockMvc mvc; @Test void tHdr001NonceCspAndBrowserHeaders(){assertDoesNotThrow(()->mvc.perform(get("/login")).andExpect(status().isOk()).andExpect(header().string("Content-Security-Policy",org.hamcrest.Matchers.containsString("default-src 'none'"))).andExpect(header().string("Content-Security-Policy",org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("unsafe-inline")))).andExpect(header().string("X-Frame-Options","DENY")).andExpect(header().string("Referrer-Policy","no-referrer")));} @Test void tHdr002TemplatesForbidUnsafeSinks() throws Exception {try(var paths=Files.walk(Path.of("src/main/resources/templates"))){for(Path p:paths.filter(Files::isRegularFile).toList()){String s=Files.readString(p);assertFalse(s.contains("th:utext"));assertFalse(s.contains("innerHTML"));assertFalse(s.contains("localStorage"));assertFalse(s.matches("(?s).*\\son[a-z]+\\s*=.*"));}}} @Test void tCors001PreflightIsRefused(){assertDoesNotThrow(()->mvc.perform(options("/cases").header("Origin","https://evil.example").header("Access-Control-Request-Method","GET")).andExpect(status().is3xxRedirection()).andExpect(header().doesNotExist("Access-Control-Allow-Origin")));} }
